const RR_CHECKIN_LIMIT=['From 24 hours to 90 minutes before your flight','De 24 h à 90 min avant votre vol'];
function rrCheckInHere(t,i,last=t.route.length-1){const air=rrCityCheckIn(t.route[i]?.[0]);if(!air)return false;
 for(let k=i+1;k<=last;k++)if(air.includes(t.route[k][0])&&timeOrdinal(t.route[k][1])-timeOrdinal(t.route[i][1])<=90)return true;return false}   /* same 90-min rule as the station's check-in */
